import { BaseMessageChannel } from './base';
import { MessageSource, GetMessageEvent, GetPayload, IWebMessageChannelOptions } from '../types';

export class WebMessageChannel<Outgoing, Incoming> extends BaseMessageChannel<Outgoing, Incoming> {
    private target: Window;
    private source: MessageSource;
    private onMessageCallback?: (event: GetMessageEvent<Incoming, keyof Incoming>) => void;

    constructor(options: IWebMessageChannelOptions) {
        super();
        this.source = options.source;
        this.onMessageCallback = options.onMessageCallback;

        if (options.target === window) {
            this.target = options.target.parent;
        } else if (options.target instanceof HTMLElement && options.target.contentWindow) {
            this.target = options.target.contentWindow;
        } else {
            throw new Error('Connection message channel target is invalid');
        }

        if (this.onMessageCallback) {
            window.addEventListener('message', (event) => this.onMessage(event));
        }
    }

    public send<T extends keyof Outgoing>(type: T, payload: GetPayload<Outgoing, T>, origin: string = '*') {
        this.target.postMessage({ source: this.source, type, payload }, origin);
    }

    public makeRequest<T extends keyof Outgoing, RT extends keyof Incoming>(type: T, payload: GetPayload<Outgoing, T>, responseType: RT, source: MessageSource): Promise<GetPayload<Outgoing, T>> {
        this.send(type, payload);
        return this.waitForResponse(responseType, source);
    }

    public waitForResponse<T extends keyof Incoming>(type: T, source: MessageSource) {
        return new Promise<GetPayload<Incoming, T>>((resolve) => {
            const onMessage = (event: GetMessageEvent<Incoming, T>) => {
                if ((event.data.type && event.data.type === type) && (event.data.source === source)) {
                    window.removeEventListener('message', onMessage);
                    resolve(event.data.payload);
                }
            };
            window.addEventListener('message', onMessage);
        });
    }

    protected onMessage<T extends keyof Incoming>(event: GetMessageEvent<Incoming, T>) {
        if (!event.data.type || !Object.keys(event.data).includes('payload')) {
            return;
        }

        if (this.onMessageCallback) {
            this.onMessageCallback(event);
        }
    }
}
